<?php
namespace Certloom\Infrastructure\Admin;

use Certloom\Domain\Job\JobStates;
use Certloom\Domain\Job\JobTypes;
use Certloom\Infrastructure\Job\JobRuntime;
use Certloom\Infrastructure\Repository\ProgramRepository;
use Certloom\Infrastructure\Repository\TemplateRepository;

if ( ! defined( 'ABSPATH' ) ) { exit; }

/** Premium reviewed CSV → durable background Bulk Issuance workflow. */
final class BulkIssuanceAdmin {
	const PAGE='certloom-bulk-issuance'; const NOTICE='certloom_bulk_notice_';
	private $runtime;
	public function __construct(JobRuntime $runtime){$this->runtime=$runtime;}
	public function register(){add_action('admin_menu',array($this,'menu'),56);add_action('admin_post_certloom_bulk_issuance_upload',array($this,'upload'));add_action('admin_post_certloom_bulk_issuance_commit',array($this,'commit'));}
	public function menu(){add_submenu_page('certloom',__('Bulk Issuance','certloom'),__('Bulk Issuance','certloom'),\Ecapla_CertVerify_Permissions::CAP_MANAGE_CREDENTIALS,self::PAGE,array($this,'render'));}
	public function render(){ $this->cap(); $job_key=isset($_GET['bulk_job'])?strtolower(sanitize_text_field(wp_unslash($_GET['bulk_job']))):''; echo '<div class="wrap certloom-shell certloom-bulk-issuance"><div class="certloom-page-head"><div><span class="certloom-eyebrow">'.esc_html__('Premium issuance workflow','certloom').'</span><h1>'.esc_html__('Bulk Issuance','certloom').'</h1><p>'.esc_html__('Review a protected CSV completely before any credential is created, then issue the accepted rows through the same immutable Manual Issuance truth path in bounded resumable background slices.','certloom').'</p></div><span class="certloom-domain-preview-badge">'.esc_html__('Normalized-domain preview','certloom').'</span></div>'; $this->notice(); echo '<div class="notice notice-warning inline"><p><strong>'.esc_html__('Authority boundary:','certloom').'</strong> '.esc_html__('Bulk Issuance is implemented inside the gated normalized-domain administration preview. Public normalized verification and PDF/PNG/JPEG authority remain closed until their final acceptance ceremonies.','certloom').'</p></div>';
		if(''!==$job_key){$job=$this->runtime->bulk_issuance()->owned_job($job_key,get_current_user_id()); if(is_wp_error($job)){echo '<div class="notice notice-error inline"><p>'.esc_html($job->get_error_message()).'</p></div>';$this->form();}else{$this->job($job);}}else{$this->form();} echo '</div>'; }
	public function upload(){ $this->cap(); check_admin_referer('certloom_bulk_issuance_upload'); if(empty($_FILES['bulk_csv'])||!is_array($_FILES['bulk_csv'])){$this->fail(__('Choose a CSV file before starting Bulk Issuance.','certloom'));} $file=$_FILES['bulk_csv']; if(UPLOAD_ERR_OK!==(int)($file['error']??UPLOAD_ERR_NO_FILE)){$this->fail(__('The Bulk Issuance CSV upload did not complete successfully.','certloom'));}$tmp=(string)($file['tmp_name']??''); if(''===$tmp||!is_file($tmp)){$this->fail(__('The temporary Bulk Issuance upload is unavailable.','certloom'));}$shared=array('program_id'=>$_POST['program_id']??0,'template_id'=>$_POST['template_id']??0,'valid_from'=>isset($_POST['valid_from'])?wp_unslash($_POST['valid_from']):'','expiry_mode'=>isset($_POST['expiry_mode'])?wp_unslash($_POST['expiry_mode']):'program','expires_at'=>isset($_POST['expires_at'])?wp_unslash($_POST['expires_at']):'','grade'=>isset($_POST['grade'])?wp_unslash($_POST['grade']):'');$key=$this->runtime->bulk_issuance()->enqueue_preflight($tmp,(string)($file['name']??'bulk.csv'),get_current_user_id(),$shared);if(is_wp_error($key)){$this->fail($key->get_error_message());}$this->success(__('Bulk Issuance review was queued. No credential has been created yet.','certloom'));$this->go($key);}
	public function commit(){ $this->cap(); $pre=isset($_POST['preflight_job_key'])?strtolower(sanitize_text_field(wp_unslash($_POST['preflight_job_key']))):'';$fp=isset($_POST['review_fingerprint'])?strtolower(sanitize_text_field(wp_unslash($_POST['review_fingerprint']))):'';check_admin_referer('certloom_bulk_issuance_commit_'.$fp);$key=$this->runtime->bulk_issuance()->enqueue_commit($pre,get_current_user_id(),$fp,true);if(is_wp_error($key)){$this->fail($key->get_error_message(),$pre);}$this->success(__('Bulk Issuance was confirmed and queued. Each row remains independently idempotent and transaction-safe.','certloom'));$this->go($key);}
	private function form(){ $programs=(new ProgramRepository())->list_page('',1,100,'active');$templates=(new TemplateRepository())->list_published_candidates(100);$p=is_wp_error($programs)?array():(array)($programs['items']??array());$t=is_wp_error($templates)?array():(array)($templates['items']??array());echo '<section class="certloom-manual-card certloom-bulk-card"><div class="certloom-manual-card-head"><div><span class="certloom-eyebrow">'.esc_html__('Step 1','certloom').'</span><h2>'.esc_html__('Upload & define shared issuance context','certloom').'</h2></div><span class="certloom-template-state">'.esc_html__('Mutation-free review','certloom').'</span></div><p>'.esc_html__('Program, resolved published design, dates and expiry policy are frozen for the batch. CSV rows provide Recipient identity plus optional row-specific grade, certificate number and custom merge values.','certloom').'</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'" enctype="multipart/form-data" class="certloom-manual-form"><input type="hidden" name="action" value="certloom_bulk_issuance_upload">';wp_nonce_field('certloom_bulk_issuance_upload');echo '<div class="certloom-manual-grid certloom-manual-grid-2"><label><span>'.esc_html__('Active Program','certloom').'</span><select name="program_id" required><option value="">'.esc_html__('Choose Program','certloom').'</option>';foreach($p as $x){echo '<option value="'.esc_attr((string)absint($x['id']??0)).'">'.esc_html((string)($x['title']??'')).'</option>';}echo '</select></label><label><span>'.esc_html__('Certificate design','certloom').'</span><select name="template_id"><option value="0">'.esc_html__('Use Program design automatically','certloom').'</option>';foreach($t as $x){echo '<option value="'.esc_attr((string)absint($x['id']??0)).'">'.esc_html((string)($x['name']??$x['title']??'')).'</option>';}echo '</select></label><label><span>'.esc_html__('Issue / effective date','certloom').'</span><input type="date" name="valid_from" required value="'.esc_attr(gmdate('Y-m-d')).'"></label><label><span>'.esc_html__('Default grade (optional)','certloom').'</span><input type="text" maxlength="191" name="grade"></label></div><div class="certloom-manual-choice-row"><label><input type="radio" name="expiry_mode" value="program" checked> '.esc_html__('Use Program validity','certloom').'</label><label><input type="radio" name="expiry_mode" value="permanent"> '.esc_html__('Permanent','certloom').'</label><label><input type="radio" name="expiry_mode" value="date"> '.esc_html__('Specific expiry','certloom').'</label></div><label class="certloom-bulk-expiry"><span>'.esc_html__('Specific expiry date','certloom').'</span><input type="date" name="expires_at"></label><div class="certloom-bulk-csv"><label><span>'.esc_html__('Bulk Issuance CSV','certloom').'</span><input type="file" name="bulk_csv" accept=".csv,text/csv" required></label><div class="certloom-bulk-schema"><strong>'.esc_html__('Accepted columns','certloom').'</strong><code>recipient_id</code> <em>'.esc_html__('or','certloom').'</em> <code>display_name</code> + <code>email</code>/<code>external_id</code>, <code>first_name</code>, <code>middle_name</code>, <code>last_name</code>, <code>grade</code>, <code>certificate_number</code>, <code>custom:machine_key</code>.</div></div><div class="certloom-manual-actions"><button class="button button-primary button-hero" type="submit" '.(empty($p)?'disabled':'').'>'.esc_html__('Review CSV','certloom').'</button><span>'.esc_html__('Review runs in bounded background slices and never issues credentials.','certloom').'</span></div></form></section>'; }
	private function job(array $job){$type=(string)($job['job_type']??'');$status=(string)($job['status']??'');$result=is_array($job['result']??null)?$job['result']:array();$summary=is_array($result['summary']??null)?$result['summary']:array();echo '<section class="certloom-manual-card certloom-bulk-card"><div class="certloom-manual-card-head"><div><span class="certloom-eyebrow">'.esc_html(JobTypes::BULK_ISSUANCE_PREFLIGHT===$type?__('Step 2','certloom'):__('Step 3','certloom')).'</span><h2>'.esc_html(JobTypes::BULK_ISSUANCE_PREFLIGHT===$type?__('Bulk review','certloom'):__('Bulk issuance progress','certloom')).'</h2></div><span class="certloom-bulk-status is-'.esc_attr(sanitize_html_class($status)).'">'.esc_html(str_replace('_',' ',ucfirst($status))).'</span></div>';$this->metrics($type,$summary);if(!empty($summary['error_details'])){echo '<div class="notice notice-error inline"><p><strong>'.esc_html__('Row issues','certloom').'</strong></p><ol class="certloom-bulk-errors">';foreach(array_slice((array)$summary['error_details'],0,25) as $e){echo '<li><strong>'.esc_html(sprintf(__('Row %d','certloom'),absint($e['row']??0))).':</strong> '.esc_html((string)($e['message']??'')).'</li>';}echo '</ol></div>';}
		if(in_array($status,array(JobStates::QUEUED,JobStates::RUNNING),true)){echo '<p>'.esc_html__('This durable job is still processing. Refresh to see the latest committed slice; duplicate/racing workers cannot claim the same lease.','certloom').'</p><a class="button button-primary" href="'.esc_url(add_query_arg(array('page'=>self::PAGE,'bulk_job'=>(string)$job['job_key']),admin_url('admin.php'))).'">'.esc_html__('Refresh progress','certloom').'</a>';}elseif(JobTypes::BULK_ISSUANCE_PREFLIGHT===$type&&!empty($result['ready_for_issue'])){$fp=(string)$result['review_fingerprint'];echo '<div class="certloom-template-preview-proof"><div><span>'.esc_html__('Reviewed batch SHA-256','certloom').'</span><code>'.esc_html($fp).'</code></div><div><span>'.esc_html__('Protected plan SHA-256','certloom').'</span><code>'.esc_html((string)($result['plan_sha256']??'')).'</code></div></div><div class="notice notice-info inline"><p>'.esc_html__('Confirming creates a separate durable job. Every row revalidates its exact Manual Issuance review fingerprint before mutation; stale rows fail individually instead of being issued against changed data.','certloom').'</p></div><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="certloom_bulk_issuance_commit"><input type="hidden" name="preflight_job_key" value="'.esc_attr((string)$job['job_key']).'"><input type="hidden" name="review_fingerprint" value="'.esc_attr($fp).'">';wp_nonce_field('certloom_bulk_issuance_commit_'.$fp);echo '<button class="button button-primary button-hero" type="submit">'.esc_html__('Issue reviewed batch','certloom').'</button></form>';}elseif(JobTypes::BULK_ISSUANCE_PREFLIGHT===$type){echo '<p><strong>'.esc_html__('Nothing was issued.','certloom').'</strong> '.esc_html__('Correct the blocking CSV rows and upload a new review.','certloom').'</p><a class="button" href="'.esc_url(admin_url('admin.php?page='.self::PAGE)).'">'.esc_html__('Start new review','certloom').'</a>';}else{echo '<p><strong>'.esc_html__('Bulk job complete.','certloom').'</strong> '.esc_html__('Credential Management now contains every successfully issued Series/Version. Email Delivery and Recipient Portal are available as separate follow-up workflows.','certloom').'</p><a class="button button-primary" href="'.esc_url(admin_url('admin.php?page=certloom-credentials')).'">'.esc_html__('Open Credential Management','certloom').'</a> ';echo '<a class="button" href="'.esc_url(admin_url('admin.php?page='.self::PAGE)).'">'.esc_html__('Issue another batch','certloom').'</a>'; } echo '</section>'; }
	private function metrics($type,array $s){$items=JobTypes::BULK_ISSUANCE_PREFLIGHT===$type?array(__('Processed','certloom')=>absint($s['processed']??0),__('Ready','certloom')=>absint($s['ready']??0),__('Errors','certloom')=>absint($s['errors']??0)):array(__('Processed','certloom')=>absint($s['processed']??0),__('Issued','certloom')=>absint($s['succeeded']??0),__('Failed','certloom')=>absint($s['failed']??0),__('Idempotent replays','certloom')=>absint($s['idempotent_replays']??0));echo '<div class="certloom-bulk-metrics">';foreach($items as $label=>$value){echo '<div><span>'.esc_html($label).'</span><strong>'.esc_html(number_format_i18n($value)).'</strong></div>';}echo '</div>';}
	private function cap(){if(!current_user_can(\Ecapla_CertVerify_Permissions::CAP_MANAGE_CREDENTIALS)){wp_die(esc_html__('You do not have permission to issue Certloom credentials.','certloom'));}}
	private function go($key){wp_safe_redirect(add_query_arg(array('page'=>self::PAGE,'bulk_job'=>(string)$key),admin_url('admin.php')));exit;}
	private function fail($message,$key=''){$this->store('error',$message);$this->go($key);}
	private function success($message){$this->store('success',$message);}
	private function store($type,$message){set_transient(self::NOTICE.get_current_user_id(),array('type'=>$type,'message'=>(string)$message),120);}
	private function notice(){$k=self::NOTICE.get_current_user_id();$n=get_transient($k);if(!is_array($n)||empty($n['message']))return;delete_transient($k);echo '<div class="notice '.('success'===($n['type']??'')?'notice-success':'notice-error').' is-dismissible"><p>'.esc_html((string)$n['message']).'</p></div>';}
}
